                    {"Kategori Penolakan Filter": "Quote orderbook/ticker kedaluwarsa (> 60s)", "Kode": "rejected_stale_quote", "Jumlah Pair": int(rej_bd.get("rejected_stale_quote", 0))},
                    {"Kategori Penolakan Filter": "Data candle / orderbook tidak tersedia", "Kode": "rejected_missing_candle", "Jumlah Pair": int(rej_bd.get("rejected_missing_candle", 0))},
                    {"Kategori Penolakan Filter": "Simbol tidak aktif / non-USDT / non-perpetual", "Kode": "rejected_invalid_symbol", "Jumlah Pair": int(rej_bd.get("rejected_invalid_symbol", 0))},
                    {"Kategori Penolakan Filter": "Rentang intraday di luar batas (0.5%–30%)", "Kode": "rejected_intraday_range", "Jumlah Pair": int(rej_bd.get("rejected_intraday_range", 0))},
